export function mustSegregate(a: string, b: string): boolean {
  const na = a.trim();
  const nb = b.trim();
  const left = SEGREGATION[na] ?? [];
  const right = SEGREGATION[nb] ?? [];
  return left.includes(nb) || right.includes(na);
}

